<?php declare(strict_types=1);require_once __DIR__.'/bootstrap.php';$s=['max_upload_mb'=>100,'default_mode'=>'smart','language'=>'en','theme'=>'light','timezone'=>'Asia/Kuala_Lumpur'];if(is_file(SETTINGS_FILE))$s=array_merge($s,json_decode((string)file_get_contents(SETTINGS_FILE),true)?:[]);if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf($_POST['csrf']??null);$s['max_upload_mb']=max(1,min(100,(int)($_POST['max_upload_mb']??100)));$s['default_mode']=in_array($_POST['default_mode']??'', ['smart','exact'],true)?$_POST['default_mode']:'smart';$s['language']=in_array($_POST['language']??'', ['en','zh','ms'],true)?$_POST['language']:'en';$s['theme']=in_array($_POST['theme']??'', ['light','dark'],true)?$_POST['theme']:'light';$s['timezone']=trim((string)($_POST['timezone']??'Asia/Kuala_Lumpur'));file_put_contents(SETTINGS_FILE,json_encode($s,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),LOCK_EX);$ok='Settings saved.';}catch(Throwable $e){$ok=$e->getMessage();}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Settings</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/app.css" rel="stylesheet"></head><body><aside class="sidebar"><div class="brand">Student Compare</div><a href="index.php">Compare</a><a href="history.php">History</a><a class="active" href="settings.php">Settings</a></aside><main class="content"><h2>Settings</h2><?php if(isset($ok)):?><div class="alert alert-info mt-3"><?=e($ok)?></div><?php endif;?><div class="card border-0 shadow-sm mt-4"><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-4"><label class="form-label">Maximum upload MB</label><input class="form-control" name="max_upload_mb" type="number" min="1" max="100" value="<?=e($s['max_upload_mb'])?>"></div><div class="col-md-4"><label class="form-label">Default mode</label><select class="form-select" name="default_mode"><option value="smart" <?=$s['default_mode']==='smart'?'selected':''?>>Smart</option><option value="exact" <?=$s['default_mode']==='exact'?'selected':''?>>Exact</option></select></div><div class="col-md-4"><label class="form-label">Language</label><select class="form-select" name="language"><option value="en">English</option><option value="zh">中文</option><option value="ms">Malay</option></select></div><div class="col-md-4"><label class="form-label">Theme</label><select class="form-select" name="theme"><option value="light">Light</option><option value="dark">Dark</option></select></div><div class="col-md-4"><label class="form-label">Timezone</label><input class="form-control" name="timezone" value="<?=e($s['timezone'])?>"></div></div><button class="btn btn-primary mt-4">Save Settings</button></form></div></div></main></body></html>
